CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY CHECK(version>0),checksum TEXT NOT NULL,applied_at TEXT NOT NULL);
CREATE TABLE library_identity(singleton INTEGER PRIMARY KEY CHECK(singleton=1),library_id TEXT NOT NULL UNIQUE);
CREATE TABLE venues(id TEXT PRIMARY KEY,name TEXT NOT NULL CHECK(length(trim(name))>0),kind TEXT,identifier TEXT);
CREATE TABLE authors(id TEXT PRIMARY KEY,display_name TEXT NOT NULL CHECK(length(trim(display_name))>0),orcid TEXT);
CREATE TABLE papers(id TEXT PRIMARY KEY,title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 1000),doi TEXT UNIQUE CHECK(doi IS NULL OR (doi=lower(trim(doi)) AND doi LIKE '10.%/%')),year INTEGER CHECK(year IS NULL OR year BETWEEN 1000 AND 9999),review_type TEXT NOT NULL CHECK(review_type IN('survey','topical_review','slr','mapping_study','tutorial','other','unknown')),domain TEXT,url TEXT,venue_id TEXT REFERENCES venues(id),lifecycle TEXT NOT NULL DEFAULT 'NEW' CHECK(lifecycle IN('NEW','ACTIVE','COMPLETED','ARCHIVED','TRASHED')),archived_from_lifecycle TEXT CHECK(archived_from_lifecycle IS NULL OR archived_from_lifecycle IN('NEW','ACTIVE','COMPLETED')),revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0),current_phase TEXT CHECK(current_phase IS NULL OR current_phase IN('PRE','P1','P2','P3','P4')),processing_initialized INTEGER NOT NULL DEFAULT 0 CHECK(processing_initialized IN(0,1)),active_document_id TEXT REFERENCES documents(id) DEFERRABLE INITIALLY DEFERRED,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,last_opened_at TEXT);
CREATE TABLE paper_authors(paper_id TEXT NOT NULL REFERENCES papers(id),author_id TEXT NOT NULL REFERENCES authors(id),author_order INTEGER NOT NULL CHECK(author_order>=0),PRIMARY KEY(paper_id,author_order),UNIQUE(paper_id,author_id));
CREATE TABLE documents(id TEXT PRIMARY KEY,paper_id TEXT NOT NULL REFERENCES papers(id),original_filename TEXT NOT NULL,relative_path TEXT NOT NULL UNIQUE CHECK(length(relative_path)>0 AND substr(relative_path,1,1) NOT IN('/','\') AND instr(relative_path,':')=0 AND instr(relative_path,'..')=0 AND instr(relative_path,'\')=0),sha256 TEXT NOT NULL CHECK(length(sha256)=64),media_type TEXT NOT NULL CHECK(media_type='application/pdf'),size_bytes INTEGER NOT NULL CHECK(size_bytes BETWEEN 0 AND 524288000),imported_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('ACTIVE','SUPERSEDED','MISSING')));
CREATE UNIQUE INDEX documents_active_paper ON documents(paper_id) WHERE status='ACTIVE';
CREATE INDEX documents_paper ON documents(paper_id);
CREATE INDEX documents_hash ON documents(sha256);
CREATE INDEX papers_lifecycle_updated ON papers(lifecycle,updated_at);
CREATE TABLE import_operations(id TEXT PRIMARY KEY,import_token TEXT NOT NULL UNIQUE,request_id TEXT,library_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('STAGING','PROMOTED','COMMITTED','FAILED')),staging_path TEXT NOT NULL CHECK(instr(staging_path,'..')=0 AND instr(staging_path,':')=0),destination_path TEXT CHECK(destination_path IS NULL OR (instr(destination_path,'..')=0 AND instr(destination_path,':')=0)),original_filename TEXT NOT NULL,source_path_private TEXT,sha256 TEXT,size_bytes INTEGER CHECK(size_bytes IS NULL OR size_bytes BETWEEN 0 AND 524288000),reserved_paper_id TEXT,reserved_document_id TEXT,metadata_json TEXT CHECK(metadata_json IS NULL OR json_valid(metadata_json)),payload_hash TEXT,result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)),error_json TEXT CHECK(error_json IS NULL OR json_valid(error_json)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE reading_positions(document_id TEXT PRIMARY KEY REFERENCES documents(id),page_index INTEGER NOT NULL CHECK(page_index>=1),zoom REAL NOT NULL CHECK(zoom BETWEEN 0.25 AND 5.0),revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0),updated_at TEXT NOT NULL);
CREATE TABLE app_session(singleton INTEGER PRIMARY KEY CHECK(singleton=1),last_opened_paper_id TEXT REFERENCES papers(id));
INSERT INTO app_session VALUES(1,NULL);
CREATE TABLE app_settings(key TEXT PRIMARY KEY,value_json TEXT NOT NULL CHECK(json_valid(value_json)));
CREATE TABLE operation_receipts(request_id TEXT PRIMARY KEY,command TEXT NOT NULL,payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64),result_json TEXT NOT NULL CHECK(json_valid(result_json)),created_at TEXT NOT NULL);
CREATE TABLE audit_events(id TEXT PRIMARY KEY,request_id TEXT,action TEXT NOT NULL,entity_id TEXT,changes_json TEXT NOT NULL CHECK(json_valid(changes_json)),created_at TEXT NOT NULL);
CREATE TABLE maintenance_operations(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('export','backup','restore','switch')),state TEXT NOT NULL CHECK(state IN('queued','running','completed','failed','cancelled')),progress REAL CHECK(progress IS NULL OR progress BETWEEN 0 AND 1),result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)),error_json TEXT CHECK(error_json IS NULL OR json_valid(error_json)),resources_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(resources_json)),cancellation_requested INTEGER NOT NULL DEFAULT 0 CHECK(cancellation_requested IN(0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
